	</view>
</template>

<script>
	var _this;
	export default {
		data() {
			return {
				order_id:0,
			}
		},
		onLoad(e) {
			_this = this;
			if(e.order_id){
				_this.order_id = e.order_id
			}else{
				this.$u.toast('提交参数有误')
				setTimeout(()=>{
					_this.finish()
				},2000)
				return
			}
			_this.get_dingdan_xq()
		},
		methods: {
			copy(){
				uni.setClipboardData({
					data: _this.detail.order_sn,
					success: function () {
						uni.$u.toast('复制成功');
					}
				});
			},
			async get_dingdan_xq(){
				const params = {
					order_id: _this.order_id,
				}
				const data = await _this.$post('port/jf_dingdan_xq', params)
				if(data.code==200){
					_this.detail = data.result.order
					if (_this.load) {
						_this.load = false
					}
				}else{
					this.$u.toast(data.msg)
				}
			}
		}
	}
</script>

